head.script:
let curID = '';
let oldID = '';


// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > id]<br/>DataList 모듈의 Column ID 를 설정합니다.",
    "validation" : [
        "동일 Scope 에서 DataList 모듈의 Column ID 를 구별할 수 있는 유일값을 설정합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    curID = con_ID.getText();

    // 기존 target 있으면 삭제
    if (typeof scwin[oldID] !== 'undefined') {
        $p.data.remove(oldID);
    }    

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }    

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    let strGridView = '';    
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:dataList ' + strNameSpace + ' id="dataList1" baseNode="list" repeatNode="map">';        
    strTarget += '<w2:columnInfo>';
    strTarget += '<w2:column id="'+ curID +'" name="name1" dataType="text"></w2:column>';
    strTarget += '</w2:columnInfo>';
    strTarget += '<w2:data use="true">';
    strTarget += '<w2:row>';
    strTarget += '<'+ curID +'><![CDATA[col1_1]]></'+ curID +'>';
    strTarget += '<col2><![CDATA[col2_1]]></col2>';
    strTarget += '<col3><![CDATA[col3_1]]></col3>';
    strTarget += '<col4><![CDATA[col4_1]]></col4>';
    strTarget += '</w2:row>';
    strTarget += '</w2:data>';
    strTarget += '</w2:dataList>';    

    // target 생성
    $p.data.create(strTarget);

    let arrResult = $p.data.getAllDataCollection("object");
    scwin["dataList1"] = arrResult[arrResult.length-1];

    oldID = curID;

    // gridView 생성
    strGridView += '<w2:gridView ' + strNameSpace + ' rowStatusVisible="true" checkAllType="false" id="gridView1" dataList="dataList1" style="width:500px;height:300px;" ev:onsort="scwin.gridView1_onsort">';
    strGridView += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strGridView += '<w2:header style="" id="header1">';
    strGridView += '<w2:row style="" id="row1">';
    strGridView += '<w2:column width="120" style="" inputType="text" id="column1" value="name1"></w2:column>';    
    strGridView += '</w2:row>';
    strGridView += '</w2:header>';
    strGridView += '<w2:gBody style="" id="gBody1">';
    strGridView += '<w2:row style="" id="row2">';
    strGridView += '<w2:column width="120" style="" id="'+ curID +'" value=""></w2:column>';    
    strGridView += '</w2:row>';
    strGridView += '</w2:gBody>';
    strGridView += '</w2:gridView>';    

    // gridView 생성
    scwin["gridView1"] = await $p.dynamicCreate(
        "gridView1",
        "gridView",
        strGridView,
        grp_comp
    );    

    scwin.btn_getID_onclick();
}



scwin.btn_getID_onclick = function (e) {
    let rtn = $p.data.getInfo(["mf_dataList1"]);
    let id = eval("rtn.mf_dataList1.columnInfo." + curID + ".id");

    wf_body_bottom.getObj("scwin").setReturnValue("id : " +id);
};
